import { HEVCDecoder } from 'hevc.js';
const decoder = await HEVCDecoder.create();
const { frames, info } = decoder.decode(bitstreamBytes);

// Video.js integration
import 'hevc.js/videojs';
const player = videojs('my-video', { techOrder: ['html5', 'HevcWasm'] });
```

